// sw.js – Service Worker with Workbox
// Import Workbox from CDN
importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.5.4/workbox-sw.js');

if (workbox) {
  console.log('✅ Workbox loaded');
  // Precache the assets generated by Workbox build (self.__WB_MANIFEST is injected at build time)
  workbox.precaching.precacheAndRoute(self.__WB_MANIFEST || []);
  // Runtime caching for API requests (price updates, etc.)
  workbox.routing.registerRoute(
    ({url}) => url.origin === self.location.origin && url.pathname.startsWith('/api/'),
    new workbox.strategies.NetworkFirst({
      cacheName: 'api-cache',
      networkTimeoutSeconds: 5,
      plugins: [
        new workbox.expiration.ExpirationPlugin({maxEntries: 200, maxAgeSeconds: 24 * 60 * 60})
      ]
    })
  );
} else {
  console.error('❌ Workbox failed to load');
}

// Listen for messages from the client (e.g., cache update requests)
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
  if (event.data && event.data.type === 'CACHE_PRICE_UPDATE') {
    // Force a cache update for the price endpoint
    fetch(event.data.url, {cache: 'no-store'}).then(() => {
      console.log('💾 Price cache refreshed');
    }).catch((e) => console.error('Cache update error', e));
  }
});
